// ----------------------
// DATA BASE
// ----------------------

let data = $input.first()?.json?.data || [];

if (!Array.isArray(data)) {
  data = [];
}

// ----------------------
// INPUTS
// ----------------------

// nombres
let rawFiltro =
  $("When Executed by Another Workflow").first()?.json?.products_name || "";

// ids
let rawIds =
  $("webhook data").first()?.json?.data?.[0]?.products_product_id || [];

// ----------------------
// NORMALIZAR
// ----------------------

// nombres → array limpio
let filtro = Array.isArray(rawFiltro) ? rawFiltro : [rawFiltro];
filtro = filtro
  .map(f => (f || "").toLowerCase().trim())
  .filter(f => f);

// ids → array de números válidos
let ids = Array.isArray(rawIds) ? rawIds : [rawIds];
ids = ids
  .map(id => Number(id))
  .filter(id => !isNaN(id));

// ----------------------
// FILTRADO PRINCIPAL
// ----------------------

let resultado = data.filter(item => {
  const id = Number(item.id);
  const nombre = (item.name || "").toLowerCase();

  // prioridad: ID
  if (ids.length && ids.includes(id)) return true;

  // fallback: nombre
  if (filtro.length && filtro.some(f => nombre.includes(f))) return true;

  return false;
});

// ----------------------
// DETECTAR FALTANTES (IMPORTANTE)
// ----------------------

let encontradosIds = resultado.map(p => Number(p.id));
let faltantesIds = ids.filter(id => !encontradosIds.includes(id));

// ----------------------
// CONTADOR
// ----------------------

let chat_counter =
  $("Execute a SQL query").first()?.json?.result || 0;

// ----------------------
// ASIGNACIÓN DE AGENTE
// ----------------------

let lead_org = 0;
let lead_property = 0;

const isSunday = new Date().getDay() === 0;

if (isSunday) {
  const possibleUsers = [6, 8];
  lead_property =
    possibleUsers[Math.floor(Math.random() * possibleUsers.length)];
} else {
  const possibleUsers = [1, 2, 3, 5, 6];
  lead_property =
    possibleUsers[Math.floor(Math.random() * possibleUsers.length)];
}

// ----------------------
// ASIGNACIÓN DE SUCURSAL
// ----------------------

if (chat_counter) {
  switch (lead_property) {
    case 4:
      if (!isSunday) lead_org = 1;
      break;

    case 5:
      if (!isSunday) lead_org = 2;
      break;

    case 6:
    case 8:
      lead_org = 3;
      break;

    default:
      lead_org = 0;
  }
} else {
  lead_property = 1;
  lead_org = 4;
}

// ----------------------
// OUTPUT FINAL
// ----------------------

return [
  {
    json: {
      randomUser: lead_property,
      randomOrg: lead_org,
      data: resultado,

      // debug útil
      filtro_usado: filtro,
      ids_usados: ids,
      total_productos_filtrados: resultado.length,
      faltantes_ids: faltantesIds // 🔥 clave para saber qué no encontró
    },
  },
];

